        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalPts = history.reduce(function(s, r) { return s + (r.results ? r.results.pointsEarned : 0); }, 0);
            var maxPts = history.length * 100;
            var avgAccuracy = history.reduce(function(s, r) { return s + (r.results ? r.results.accuracy : 0); }, 0) / history.length;
            var severityMatches = history.filter(function(r) { return r.results && r.results.severityMatch; }).length;

            var pct = Math.round((totalPts / maxPts) * 100);
            var T = function(k) { return window.mySimulation.t(k); };
            var performance = T('perf_needs_dev');
            if (pct >= 80 && avgAccuracy >= 75) performance = T('perf_expert');
            else if (pct >= 60 && avgAccuracy >= 55) performance = T('perf_competent');
            else if (pct >= 40) performance = T('perf_developing');

            var insights = [];
            if (avgAccuracy >= 75) {
                insights.push(T('insight_acc_high'));
            } else if (avgAccuracy >= 50) {
                insights.push(T('insight_acc_mid'));
            } else {
                insights.push(T('insight_acc_low'));
            }

            if (severityMatches >= 5) {
                insights.push(T('insight_sev_good'));
            } else {
                insights.push(T('insight_sev_weak'));
            }

            return {
                totalPoints: totalPts,
                maxPoints: maxPts,
                percentage: pct,
                averageAccuracy: Math.round(avgAccuracy),
                severityMatches: severityMatches,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.accuracy < 40) return window.mySimulation.t('hint_low_accuracy');
            if (results.accuracy >= 85) return window.mySimulation.t('hint_high_accuracy');
            if (!results.severityMatch) return window.mySimulation.t('hint_severity_mismatch');
            return null;
        }

