        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var badgeEl = document.getElementById('clauseBadge');
            var T = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; };
            if (badgeEl) badgeEl.innerHTML = String(T('clause_badge')).split('{n}').join(round.clauseNum);

            var titleEl = document.getElementById('clauseTitle');
            if (titleEl) titleEl.innerHTML = window.mySimulation ? window.mySimulation.t(round.titleKey) || round.titleDefault : round.titleDefault;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = T(round.descKey);

            var evidEl = document.getElementById('evidenceText');
            if (evidEl) evidEl.innerHTML = T(round.evidenceKey);

            var feedbackEl = document.getElementById('feedbackPanel');
            if (feedbackEl) feedbackEl.style.display = 'none';

            var compInput = document.getElementById('complianceInput');
            if (compInput) compInput.value = 65;

            var sevSelect = document.getElementById('severitySelect');
            if (sevSelect) sevSelect.value = '2';

            var priSelect = document.getElementById('prioritySelect');
            if (priSelect) priSelect.value = '2';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ISOnavigatorAdapter(), {
            simulationType: 'iso_navigator_247',
            maxPeriods: 7,
            autoSaveInterval: 30000
        });
    });

